import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.CIOzaBgM.js";const p=JSON.parse('{"title":"附录 C 同类系统对比","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/c-comparison.md","filePath":"appendix/c-comparison.md","lastUpdated":1791471399000}'),o={name:"appendix/c-comparison.md"};function n(i,t,h,l,c,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="附录-c-同类系统对比" tabindex="-1">附录 C 同类系统对比 <a class="header-anchor" href="#附录-c-同类系统对比" aria-label="Permalink to &quot;附录 C 同类系统对比&quot;">​</a></h1><blockquote><p>说明：RAGFlow 和 mini-ragflow 的内容来自本书对源码的阅读和实际运行；Dify 的内容来自作者此前对 Dify 源码的阅读（《从 Dify 到 Mini-Dify》第 22、23 章）；LlamaIndex、Haystack、Weaviate、Qdrant 只列出公开文档中广为人知的设计，作者没有在本书中运行它们，细节以各自的最新文档为准。</p></blockquote><h2 id="c-1-定位" tabindex="-1">C.1 定位 <a class="header-anchor" href="#c-1-定位" aria-label="Permalink to &quot;C.1 定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>是什么</th><th>谁来用</th></tr></thead><tbody><tr><td><strong>RAGFlow</strong></td><td>一个完整的知识库平台：上传/同步 → 深度解析 → 切块 → 检索 → 问答，带界面和多租户</td><td>想直接部署一套知识库服务的团队</td></tr><tr><td><strong>Dify</strong></td><td>LLM 应用平台，知识库是其中一个模块，主要服务于工作流和 Agent</td><td>想搭建各种 LLM 应用、知识库只是其中一环的团队</td></tr><tr><td><strong>LlamaIndex / Haystack</strong></td><td>Python 库/框架，提供构建 RAG 的组件（加载器、切分器、检索器、管线）</td><td>写代码自己组装 RAG 的开发者</td></tr><tr><td><strong>Weaviate / Qdrant</strong></td><td>向量数据库，原生支持混合检索</td><td>作为 RAG 系统的存储与检索层</td></tr><tr><td><strong>mini-ragflow</strong></td><td>本书的教学实现，结构照着 RAGFlow，规模小两个数量级</td><td>读者</td></tr></tbody></table><h2 id="c-2-入库" tabindex="-1">C.2 入库 <a class="header-anchor" href="#c-2-入库" aria-label="Permalink to &quot;C.2 入库&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>解析</th><th>切块</th><th>入库增强</th></tr></thead><tbody><tr><td>RAGFlow</td><td>DeepDoc：版面分析、表格结构识别、OCR；也可接 MinerU、PaddleOCR 等（第 8 章）</td><td>按文档类型选模板：general/book/laws/qa/table/one……，可视化的流水线（第 7、9 章）</td><td>Extractor（关键词、问题、元数据）、RAPTOR、思维导图/结构图/Wiki 等知识编译（第 18、20 章）</td></tr><tr><td>Dify</td><td>按文件类型分派的 extractor，可接 Unstructured 服务</td><td>分隔符 + 递归切分 + 重叠；父子分段</td><td>问答模式（为分段生成问题）</td></tr><tr><td>LlamaIndex / Haystack</td><td>各种 Reader/Converter，第三方解析服务</td><td>多种 splitter / node parser</td><td>由用户自己用组件组合</td></tr><tr><td>mini-ragflow</td><td>Markdown/HTML/文本/DOCX/CSV/XLSX 自己解析，PDF 用 <code>pdftotext</code></td><td>6 个模板，title/general/qa/table/one</td><td>Extractor、RAPTOR（watershed）</td></tr></tbody></table><p>RAGFlow 的特点是&quot;<strong>解析优先</strong>&quot;：它投入最多的是把 PDF、扫描件、表格<strong>读对</strong>，以及针对不同文档类型的切块模板。它的口号是 &quot;Quality in, quality out&quot;。</p><h2 id="c-3-检索" tabindex="-1">C.3 检索 <a class="header-anchor" href="#c-3-检索" aria-label="Permalink to &quot;C.3 检索&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>全文</th><th>向量</th><th>融合</th><th>重排</th></tr></thead><tbody><tr><td>RAGFlow</td><td>ES/Infinity/OpenSearch 的全文检索，多字段加权（<code>title_tks^10</code>、<code>important_kwd^30</code>……），<code>*_tks</code> 字段只看是否出现（第 11、12 章）</td><td>引擎内 kNN，全文查询作为 kNN 的过滤条件（ES）</td><td>应用内二次打分：<code>(1-w)·tsim + w·vsim</code>，w 默认 0.3；空结果时放宽 <code>min_match</code>、降低阈值，最后退回纯向量（第 13 章）</td><td>可选重排模型；还有 pagerank 和标签特征</td></tr><tr><td>Dify</td><td>由向量库提供（或经济模式下的 jieba 关键词表）</td><td>由向量库提供</td><td>加权融合（关键词分数用 TF-IDF 余弦），或交给重排模型</td><td>重排模型</td></tr><tr><td>Weaviate</td><td>BM25</td><td>HNSW 等</td><td><code>hybrid</code> 查询，<code>alpha</code> 控制两路权重，提供 ranked / relative-score 两种融合</td><td>可接重排模块</td></tr><tr><td>Qdrant</td><td>稀疏向量</td><td>稠密向量</td><td>Query API 用 prefetch 组合多路结果，支持 RRF 等融合</td><td>可在外部做</td></tr><tr><td>mini-ragflow</td><td>内存倒排 + BM25（<code>*_tks</code> 只看是否出现）</td><td>暴力余弦</td><td>照搬 RAGFlow 的二次打分和重试</td><td>可选 rerank 模型</td></tr></tbody></table><p>RAGFlow 的检索比&quot;向量库 + 加权融合&quot;多了一层<strong>应用内的二次打分</strong>：引擎负责召回，最终的分数在应用里重新计算。这让它能把检索词权重、标签、pagerank 这些引擎不知道的信号加进来，也让检索测试页能展示&quot;全文分 / 向量分 / 总分&quot;（第 14 章）。代价是每次检索都要把一批候选拉回应用。</p><h2 id="c-4-问答与引用" tabindex="-1">C.4 问答与引用 <a class="header-anchor" href="#c-4-问答与引用" aria-label="Permalink to &quot;C.4 问答与引用&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>引用</th><th>不知道时</th><th>多步检索</th></tr></thead><tbody><tr><td>RAGFlow</td><td>提示词要求 <code>[ID:n]</code>；生成后修复格式、校验编号；模型没有引用时按向量相似度回填（第 16 章）</td><td>检索为空且配置了 <code>empty_response</code> 时直接返回它，不调用 LLM；没配置则仍调用 LLM</td><td>思考等级 1~4 的研究循环、等级 5 的 smart-reasoning 智能体（第 21 章）</td></tr><tr><td>Dify</td><td>返回检索到的分段作为&quot;引用与归属&quot;，回答文本中一般不插入编号</td><td>由提示词和工作流决定</td><td>用工作流或 Agent 自己编排</td></tr><tr><td>mini-ragflow</td><td>同 RAGFlow，另外能识别&quot;拒答&quot;并去掉引用</td><td>同 RAGFlow</td><td>无</td></tr></tbody></table><h2 id="c-5-平台" tabindex="-1">C.5 平台 <a class="header-anchor" href="#c-5-平台" aria-label="Permalink to &quot;C.5 平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>多租户</th><th>数据源同步</th><th>对外接口</th><th>任务系统</th></tr></thead><tbody><tr><td>RAGFlow</td><td>用户即租户，团队成员通过 <code>user_tenant</code> 共享</td><td>41 个连接器，增量窗口 + 断点续传 + 完整快照删除（第 25 章）</td><td>REST、OpenAI 兼容、Dify 外部知识库、MCP（第 23 章）</td><td>NATS JetStream + 数据库状态（第 24 章）</td></tr><tr><td>Dify</td><td>工作空间（workspace）</td><td>数据源插件</td><td>应用 API、知识库 API</td><td>Celery + Redis</td></tr><tr><td>mini-ragflow</td><td>用户即租户，无团队</td><td>一个文件夹连接器</td><td>同 RAGFlow 的三种</td><td>SQLite 任务表 + 租约</td></tr></tbody></table><h2 id="c-6-mini-ragflow-与-ragflow-的差距一览" tabindex="-1">C.6 mini-ragflow 与 RAGFlow 的差距一览 <a class="header-anchor" href="#c-6-mini-ragflow-与-ragflow-的差距一览" aria-label="Permalink to &quot;C.6 mini-ragflow 与 RAGFlow 的差距一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方面</th><th>RAGFlow</th><th>mini-ragflow</th></tr></thead><tbody><tr><td>规模</td><td><code>internal/</code> 和 <code>cmd/</code> 下非测试 Go 代码约 49 万行，外加 Python 遗留代码和前端</td><td>后端约 9700 行 Go（不含测试），前端十几个页面</td></tr><tr><td>存储</td><td>MySQL/PostgreSQL + MinIO + ES/Infinity/OpenSearch + Kvrocks + NATS</td><td>一个 SQLite 文件 + 本地目录</td></tr><tr><td>解析</td><td>DeepDoc（ONNX 模型、版面、表格、OCR）</td><td>文本类格式 + <code>pdftotext</code></td></tr><tr><td>检索</td><td>引擎内全文 + kNN，多种引擎</td><td>内存倒排 + 暴力余弦</td></tr><tr><td>进阶</td><td>知识图谱、知识编译（树/图/思维导图/Wiki）、Agentic RAG、Agent 画布</td><td>Extractor、RAPTOR</td></tr><tr><td>部署</td><td>一个应用容器内多进程 + 一组基础设施，可多机扩展</td><td>Compose 中按角色拆分，单机</td></tr></tbody></table><p>mini-ragflow 的价值不在于替代 RAGFlow，而在于让每一个机制都能在几百行代码里被看清、被改动、被测试。读完本书再回到 RAGFlow，你应该能在它的源码里认出这些机制，知道每一层复杂度是为了解决什么问题而存在的。</p>',17)])])}const m=d(o,[["render",n]]);export{p as __pageData,m as default};
